  "Chat with a model you choose; {mnemo} reads, writes, tags, links, moves and tidies notes with Memora's own tools. It cannot browse the web, run commands, delete for good or change the server. Keys are sealed on this server and never sent to the browser.": "Trò chuyện với mô hình bạn chọn; {mnemo} đọc, ghi, gắn thẻ, liên kết, di chuyển và sắp xếp ghi chú bằng công cụ riêng của Memora. Nó không thể duyệt web, chạy lệnh, xóa vĩnh viễn hay đổi máy chủ. Khóa được niêm phong trên máy chủ này và không bao giờ gửi tới trình duyệt.",
  "Chat with your notes agent": "Trò chuyện với tác nhân ghi chú của bạn",
