  "Checklist steps tick right on the card with a click or a tap, saved with history and live on every screen.": "Các bước danh sách kiểm được đánh dấu ngay trên thẻ bằng một lần nhấp hoặc chạm, lưu cùng lịch sử và cập nhật trực tiếp trên mọi màn hình.",
