  "Choose between 0.1 and 50 MB": "Chọn từ 0,1 đến 50 MB",
  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "Chọn trong nhiều ngôn ngữ ở Cài đặt, Giao diện, theo từng thiết bị. Tự động theo trình duyệt của bạn.",
  "Choose your vault folder": "Chọn thư mục kho của bạn",
