  "Chosen when it signs in": "Chọn khi nó đăng nhập",
  "Claude Desktop (older)": "Claude Desktop (cũ)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Claude và ChatGPT đăng nhập bằng tài khoản Memora của bạn. Không cần sao chép gì.",
  "Claude models": "Mô hình Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude đăng nhập qua OAuth nên không cần dán khóa: nó nhận khóa riêng khi bạn nhấn Cho phép. Nếu không đăng nhập, hãy kết nối là <b>Ứng dụng khác</b> và gửi tiêu đề <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor và nhiều hơn",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor và nhiều hơn nữa, mỗi ứng dụng một khóa riêng",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Claude, ChatGPT, Cursor, Codex và các ứng dụng khác đều có quyền truy cập riêng, nên bạn thấy được từng cái làm gì.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Claude, Cursor, ChatGPT và tác nhân của bạn dùng chung một Memora, truy cập được từ máy này, mạng nội bộ hoặc internet",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Claude, Cursor, ChatGPT và các script của riêng bạn đọc ghi chú của bạn và bổ sung thêm.",
