  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Kéo thẻ vào khung thư mục khác để chuyển ghi chú trên đĩa. Kéo khung theo tên để sắp xếp lại bảng; thả vào khung khác để chuyển cả thư mục. Nhấn đúp tiêu đề để đổi tên. Trên cảm ứng: kéo để di chuyển, chụm để thu phóng, nhấn giữ thẻ để di chuyển, chạm để xem trước.",
  "Drag a note here to pin it": "Kéo ghi chú vào đây để ghim",
