  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Kéo ghi chú hoặc thư mục vào một thư mục để chuyển, vào Đã ghim để ghim.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Kéo ghi chú · nhấn đúp để ghim · / tìm kiếm · #thẻ tìm thẻ · F vừa khung · 1 2 3 bố cục",
  "Drag to move the folder frame; double-click to rename": "Kéo để di chuyển khung thư mục; nhấn đúp để đổi tên",
  "Drag to move the lane. Double click the name to rename it.": "Kéo để di chuyển cột. Nhấp đúp vào tên để đổi tên.",
  "Drag to resize · double-click to reset": "Kéo để đổi cỡ · nhấn đúp để đặt lại",
  "Drag to turn · scroll to zoom · click a point to open its note": "Kéo để xoay · cuộn để thu phóng · nhấn một điểm để mở ghi chú",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Kéo để xoay · cuộn để thu phóng · nhấn một điểm để mở ghi chú · / để tìm · #thẻ tìm thẻ",
