  "Each AI app connects over MCP with its own key and permissions.": "Mỗi ứng dụng AI kết nối qua MCP bằng khóa và quyền riêng.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Mỗi ứng dụng AI bạn kết nối là một tác nhân có khóa riêng, nên bạn thấy từng cái làm gì và tắt riêng được.",
  "Each agent": "Từng tác nhân",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Mỗi tác nhân thuộc về một ứng dụng. Với ứng dụng hoặc thiết bị khác, hãy tạo tác nhân mới.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Mỗi tác nhân thuộc về một ứng dụng. Để dùng Memora trong ứng dụng khác, hãy tạo một tác nhân riêng cho nó.",
  "Each app gets its own key": "Mỗi ứng dụng có khóa riêng",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "Mỗi tác tử có một ID ngắn không bao giờ đổi, nên tên có thể đổi thoải mái. Mnemo tạo, đổi chỉ dẫn hoặc mô hình, nhắn tin, chờ, dừng, kết thúc và xóa chúng, từng cái hoặc tất cả cùng lúc, và có thể để chúng làm việc ở nền. Mỗi thẻ hiển thị Chỉ dẫn, Hoạt động và Câu trả lời.",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Mỗi loại được đo theo phần chỗ của nó: giới hạn nếu có, nếu không là phần nó dùng cộng dung lượng đĩa trống{disk}. Để trống giới hạn: không giới hạn.",
  "Each one gets its own key from Memora.": "Mỗi cái nhận một khóa riêng từ Memora.",
