  "Enter your Memora password": "Nhập mật khẩu Memora của bạn",
  "Enter your current password.": "Nhập mật khẩu hiện tại.",
  "Enter your password": "Nhập mật khẩu của bạn",
  "Entries": "Mục",
  "Error": "Lỗi",
  "Error 404": "Lỗi 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "Dù dùng hằng ngày, trình duyệt vẫn đăng nhập lại sau thời gian này. Không thể ngắn hơn thời gian không hoạt động.",
  "Every AI loses {n} tool at once. Asks first.": "Mọi AI mất {n} công cụ cùng lúc. Sẽ hỏi trước.",
  "Every AI loses {n} tools at once. Asks first.": "Mọi AI mất {n} công cụ cùng lúc. Sẽ hỏi trước.",
  "Every Kanban board in your notes": "Mọi bảng Kanban trong ghi chú của bạn",
  "Every action, newest first": "Mọi hành động, mới nhất trước",
  "Every action, newest first, with search and filters.": "Mọi hành động, mới nhất trước, có tìm kiếm và bộ lọc.",
  "Every address from one to another.": "Mọi địa chỉ từ cái này đến cái kia.",
  "Every address from the first to the last, joined by a dash.": "Mọi địa chỉ từ đầu đến cuối, nối bằng dấu gạch ngang.",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "Mỗi tác nhân thường bắt đầu từ con số không. {bold} kết nối mỗi tác nhân một lần là tất cả cùng đọc một kho và ghi lại vào đó, nên cái này học được, cái khác dùng được.",
  "Every archived card is back on the board": "Mọi thẻ đã lưu trữ đã trở lại bảng",
  "Every board with its lanes and progress. New board sits wherever New note does: the sidebar, Overview, folders, menus, search and the B key.": "Mọi bảng cùng các cột và tiến độ của chúng. Bảng mới có ở mọi nơi có Ghi chú mới: thanh bên, Tổng quan, thư mục, menu, tìm kiếm và phím B.",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "Mọi trình duyệt và tác nhân bị ngắt kết nối cho đến khi ai đó khởi động lại Memora trên máy đó. Trang này không thể khởi động lại nó.",
  "Every call shows up live in the brain and Activity": "Mỗi lệnh gọi hiện trực tiếp trong bộ não và Hoạt động",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Mọi thay đổi Mnemo thực hiện đều hiện trong Hoạt động và có thể hoàn tác từ Lịch sử.",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "Mọi thay đổi, của bạn hay của một ứng dụng, đều hiện trong Hoạt động và có thể hoàn tác từ Lịch sử.",
  "Every chat is archived.": "Mọi cuộc trò chuyện đã được lưu trữ.",
  "Every chat with your notes agent": "Mọi cuộc trò chuyện với tác nhân ghi chú của bạn",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "Mọi AI đã kết nối mất cả {n} công cụ cùng lúc và không thể đọc hay sửa ghi chú của bạn cho đến khi bạn bật lại công cụ ở đây.",
  "Every connected AI loses it at once. You can turn it back on any time.": "Mọi AI đã kết nối mất nó cùng lúc. Bạn bật lại được bất cứ lúc nào.",
  "Every connected AI loses them at once. You can turn them back on any time.": "Mọi AI đã kết nối mất chúng cùng lúc. Bạn bật lại được bất cứ lúc nào.",
  "Every connected agent loses its memory until Memora runs again.": "Mọi tác nhân đã kết nối mất trí nhớ cho đến khi Memora chạy lại.",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "Mọi thiết bị trong mạng gia đình hoặc văn phòng, viết dạng địa chỉ/kích thước: 192.168.1.0/24 bao gồm 192.168.1.0 đến 192.168.1.255.",
  "Every device on a home or office network.": "Mọi thiết bị trong mạng gia đình hoặc văn phòng.",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "Mọi ảnh trong thư mục ghi chú và nơi chúng hiển thị, cùng ảnh lưu cho các cuộc trò chuyện Mnemo.",
  "Every image is used in a note.": "Mọi ảnh đều được dùng trong ghi chú.",
  "Every note": "Mọi ghi chú",
  "Every note and link, in 3D, as a graph or on a board.": "Mọi ghi chú và liên kết, ở dạng 3D, đồ thị hoặc bảng.",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "Mọi ghi chú và thư mục con trong \"{path}\" sẽ chuyển vào {folder}; sau đó \"{name}\" bị xóa. Nếu tên đã có ở đó, sẽ thêm số vào tên.",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Mỗi ghi chú thành một thẻ ở đây, trong khung thư mục của nó. Phần hướng dẫn chỉ cách nhờ AI lưu kiến thức vào đây, hoặc tự viết ghi chú.",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Mỗi ghi chú thành một điểm sáng ở đây, nhóm theo thư mục. Phần hướng dẫn chỉ cách nhờ AI lưu kiến thức vào đây, hoặc tự viết ghi chú.",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "Mọi ghi chú gắn thẻ #{tag} ({notes}) sẽ nhận tên mới, cả #thẻ trong văn bản.",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "Mọi ghi chú gắn thẻ {tags} sẽ chỉ còn một thẻ ({notes}). Các #thẻ trong văn bản cũng đổi. Không thể hoàn tác một bước; mỗi ghi chú giữ lịch sử của nó.",
  "Every read and write by an agent shows up live, so you always know who did what.": "Mọi lượt đọc và ghi của tác nhân hiện trực tiếp, nên bạn luôn biết ai đã làm gì.",
  "Every request that reaches this rule is {verb}.": "Mọi yêu cầu đến quy tắc này sẽ {verb}.",
  "Every request. Put it last, to catch whatever the rules above did not.": "Mọi yêu cầu. Đặt cuối cùng để bắt phần các quy tắc trên chưa xử lý.",
  "Every setting and where it lives.": "Mọi cài đặt và vị trí của chúng.",
