  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Hãy tìm hiểu tôi qua các ghi chú của tôi. Xem qua kho của tôi (ghi chú gần đây, nhật ký, dự án, mọi thứ về tôi) và lưu những gì bạn biết bằng remember_owner: tôi là ai, tôi làm gì, tôi thích câu trả lời thế nào, tôi thích gì. Chỉ những điều ngắn gọn, lâu dài, tuyệt đối không lưu bí mật. Sau đó nói cho tôi trong vài dòng bạn đã lưu những gì.",
  "Gets its own agent key: read and write nodes over MCP": "Có khóa tác nhân riêng: đọc và ghi nút qua MCP",
  "Getting started": "Bắt đầu sử dụng",
  "GitHub answered HTTP {code}": "GitHub trả lời HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Cho Claude, Cursor hoặc ứng dụng MCP nào khóa riêng, rồi để nó lưu những gì nó đã biết về bạn.",
  "Give a key read-only access, or let it write too.": "Cho khóa quyền chỉ đọc, hoặc cho phép cả ghi.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Cho mỗi ứng dụng hoặc thiết bị một tác nhân riêng. Hoạt động sẽ cho thấy chính xác ai làm gì, và bạn tắt được một cái mà không ảnh hưởng cái khác.",
  "Give it a name you recognise": "Đặt tên dễ nhận ra",
  "Give the agent a name": "Đặt tên cho tác nhân",
  "Give the provider a name": "Đặt tên cho nhà cung cấp",
  "Give the tag a name: letters, digits and - _ / . only.": "Đặt tên cho thẻ: chỉ gồm chữ, số và - _ / .",
  "Glow": "Phát sáng",
