  "Go to {page}": "Đi tới {page}",
  "Goes into a Private folder. You can mark it private (folder ⋯ › Privacy) to choose which AIs may read it.": "Vào thư mục Riêng tư. Bạn có thể đặt nó ở chế độ riêng tư (thư mục ⋯ › Quyền riêng tư) để chọn AI nào được đọc.",
