  "Meet Mnemo, your notes agent": "Làm quen với Mnemo, tác nhân ghi chú của bạn",
  "Memora address (MCP endpoint)": "Địa chỉ Memora (điểm cuối MCP)",
  "Memora already uses this folder.": "Memora đã dùng thư mục này.",
  "Memora by Codrihub Tech": "Memora của Codrihub Tech",
  "Memora can save notes here": "Memora có thể lưu ghi chú ở đây",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora kiểm tra thư mục và yêu cầu bạn xác nhận trước khi chuyển. Không có gì bị di chuyển hay sao chép, và bạn chuyển lại được ở đây. Chạy trong Docker? Dùng thư mục đã gắn vào container.",
  "Memora could not start.": "Memora không khởi động được.",
  "Memora data folder": "Thư mục dữ liệu Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora kiểm tra trước xem thư mục mới có tồn tại (hoặc tạo được) và lưu được ghi chú ở đó không. Nếu kiểm tra thất bại, không có gì thay đổi.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora kiểm tra trước xem thư mục mới có tồn tại và lưu được ghi chú ở đó không. Nếu kiểm tra thất bại, không có gì thay đổi.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora bằng ngôn ngữ của bạn, Mnemo hiện kế hoạch khi làm việc, và bạn chọn nó được dùng và thấy gì.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora là ứng dụng ghi chú mà các ứng dụng AI của bạn cũng dùng được. Bạn viết, chúng đọc và ghi cùng các ghi chú, và bạn luôn thấy được điều gì đã thay đổi.",
  "Memora is free and open source": "Memora miễn phí và mã nguồn mở",
  "Memora is free and open source. A star helps others find it.": "Memora miễn phí và mã nguồn mở. Một ngôi sao giúp người khác tìm thấy.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora là trí nhớ nâng cao: sinh ra để nhớ những gì bạn và AI học được, và nhớ nhiều hơn khi bạn dùng nhiều hơn.",
  "Memora is restarting": "Memora đang khởi động lại",
  "Memora is shut down": "Memora đã tắt",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora vẫn còn trống. Hãy kết nối một ứng dụng AI, gửi một câu lệnh, và nó sẽ lưu những gì biết về bạn vào đây, dưới dạng ghi chú bạn đọc, sửa và xem trong bộ não.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora giữ danh sách thẻ của bạn để gợi ý khi bạn gõ. Làm mới nếu thiếu thẻ hoặc thẻ đã cũ.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Memora giữ mọi phiên bản của ghi chú khi thư mục kho là kho git. Chạy {cmd} một lần trong thư mục kho (xem Cấu hình, “Lịch sử phiên bản” trong tài liệu); từ đó mọi thay đổi được giữ ở đây.",
  "Memora keeps it in one place:": "Memora giữ nó ở một nơi:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora lưu mỗi ghi chú thành một tệp Markdown thuần trên máy nó chạy. Không bị khóa vào đâu: mở tệp bằng bất kỳ trình soạn thảo nào, sao lưu hoặc giữ trong Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora nói MCP qua HTTP streamable. Ứng dụng gửi khóa trong tiêu đề <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora dừng trên máy đang chạy nó. Ghi chú của bạn vẫn an toàn trên đĩa.",
  "Memora version": "Phiên bản Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Đã có Memora v{latest}. Máy chủ này đang chạy v{current}.",
  "Memora v{version} is available": "Đã có Memora v{version}",
  "Memora, open Overview": "Memora, mở Tổng quan",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: kho ghi chú bạn tự lưu trữ, với một tác nhân giúp sắp xếp.",
  "Memory used: {used} of {win}": "Bộ nhớ đã dùng: {used}/{win}",
