  "Messaged {agent}": "Đã nhắn {agent}",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "Tin nhắn và ô nhập thẳng hàng chính xác ở mọi độ rộng, bộ chọn mô hình có bề mặt riêng, trò chuyện tạm thời vừa với điện thoại, và các lựa chọn của câu hỏi không trượt đi khi bạn chạm.",
  "Middle-drag": "Kéo chuột giữa",
  "Midnight": "Nửa đêm",
  "Minimap": "Bản đồ nhỏ",
  "Minimap: click or drag to move the view": "Bản đồ nhỏ: nhấn hoặc kéo để di chuyển khung nhìn",
  "Mist": "Sương mù",
  "Mnemo (AI agent)": "Mnemo (tác nhân AI)",
  "Mnemo and agents can do on a board everything you can, over MCP, behind four Kanban permission switches that follow Ask first, Auto and Read only.": "Mnemo và các tác nhân có thể làm mọi thứ bạn làm được trên bảng, qua MCP, sau bốn công tắc quyền Kanban theo Hỏi trước, Tự động và Chỉ đọc.",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Đã ẩn nút Mnemo. Hiện lại từ Thêm, Hiện nút Mnemo.",
  "Mnemo goes on without sub-agents": "Mnemo tiếp tục mà không có tác nhân phụ",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo chưa có mô hình: thêm nhà cung cấp và các mô hình của nó trong Cài đặt, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo được tích hợp sẵn trong Memora. Kết nối khóa AI của riêng bạn rồi hỏi bằng lời thường: nó tìm, viết, gắn thẻ, liên kết và sắp xếp ghi chú giúp bạn.",
  "Mnemo is still answering in this chat": "Mnemo vẫn đang trả lời trong cuộc trò chuyện này",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo là tác nhân tích hợp sẵn trong Memora. Kết nối khóa AI của riêng bạn và hỏi bằng lời thường ngày: nó giữ ghi chú của bạn ngăn nắp trong khi các ứng dụng khác dùng chúng.",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo giữ tối đa {n} nhà cung cấp; hãy xóa một nhà cung cấp trước",
  "Mnemo knows what is due": "Mnemo biết gì sắp đến hạn",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo quản lý các tác tử phụ, giữ kế hoạch cùng cuộc trò chuyện, và cuộc trò chuyện vừa vặn hơn trên mọi màn hình.",
  "Mnemo runs its sub-agents": "Mnemo điều hành tác tử phụ",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo đã dừng sau {n} bước; hãy nói \"tiếp tục\" để đi tiếp.",
  "Mnemo's plan, live": "Kế hoạch của Mnemo, trực tiếp",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Câu hỏi của Mnemo nằm trên một dải riêng, các câu trả lời bên dưới là những hàng để chạm, nhiều bao nhiêu tùy câu hỏi.",
  "Mnemo, your notes agent": "Mnemo, tác nhân ghi chú của bạn",
