  "No notes yet. Did you send the prompt? Sometimes the app asks before it uses Memora the first time: allow it.": "Chưa có ghi chú. Bạn đã gửi câu lệnh chưa? Đôi khi ứng dụng hỏi trước khi dùng Memora lần đầu: hãy cho phép.",
