  "No skills yet. Ask {mnemo}, for example: “make a skill that tidies my meeting notes”.": "Chưa có kỹ năng. Hãy hỏi {mnemo}, ví dụ: “tạo kỹ năng sắp xếp ghi chú họp của tôi”.",
  "No sub-agents in this chat yet. When {mnemo} hands a task to one, it shows here.": "Chưa có tác nhân phụ trong cuộc trò chuyện này. Khi {mnemo} giao việc cho một cái, nó hiện ở đây.",
