  "Not done": "Chưa xong",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Chưa thực hiện: Mnemo đang ở chế độ Hỏi trước, nên các thay đổi chờ chủ sở hữu đồng ý. Hãy hỏi bằng ask_owner (nói rõ bạn sẽ đổi gì; đưa một lựa chọn với approve: true như \"Có, làm đi\"), rồi thực hiện thay đổi sau khi họ chấp thuận.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Chưa thực hiện: Mnemo đang ở chế độ Chỉ đọc, nên ghi chú không bị thay đổi. Hãy nói bạn sẽ đổi gì; chủ sở hữu có thể chuyển sang Hỏi trước hoặc Tự động trong cuộc trò chuyện.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Chưa thực hiện: cuộc trò chuyện đang ở chế độ Hỏi trước nên tác nhân phụ không thể đổi ghi chú. Hãy nói trong câu trả lời điều cần đổi; Mnemo sẽ hỏi chủ sở hữu.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Chưa thực hiện: chủ sở hữu đã tắt {tool} cho Mnemo (Cài đặt, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Chưa thực hiện: chủ sở hữu đã tắt {tool} cho các tác nhân phụ (Cài đặt, Mnemo).",
  "Not finished: the owner cut this reply before the tool returned.": "Chưa xong: chủ sở hữu đã ngắt câu trả lời này trước khi công cụ trả kết quả.",
  "Not found": "Không tìm thấy",
