  "Not started: \"{name}\" fits more than one model or none exactly. Close ones: {list}. Ask the owner which, or give the exact id.": "Chưa bắt đầu: \"{name}\" khớp với nhiều mô hình hoặc không khớp chính xác mô hình nào. Gần giống: {list}. Hãy hỏi chủ sở hữu chọn cái nào, hoặc đưa id chính xác.",
  "Not started: there is no model \"{name}\" here. Tell the owner, or leave model out to use their default model.": "Chưa bắt đầu: ở đây không có mô hình \"{name}\". Hãy báo chủ sở hữu, hoặc bỏ trống model để dùng mô hình mặc định của họ.",
  "Not sure it is on? Ask {app}: “{question}”": "Không chắc nó đã bật? Hỏi {app}: “{question}”",
