  "Notes": "Ghi chú",
  "Notes and boards share one page frame with the same spacing on phones, tablets and desktops, and the links at the foot of a note share one tidy look that folds away.": "Ghi chú và bảng dùng chung một khung trang với khoảng cách như nhau trên điện thoại, máy tính bảng và máy tính, còn các liên kết ở cuối ghi chú có chung một kiểu gọn gàng và có thể thu gọn.",
  "Notes and boards, connected": "Ghi chú và bảng, kết nối với nhau",
  "Notes and images in the notes folder.": "Ghi chú và ảnh trong thư mục ghi chú.",
  "Notes and the links between them show up here as a map. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "Ghi chú và các liên kết giữa chúng hiện ở đây như một bản đồ. Phần hướng dẫn chỉ cách nhờ AI lưu kiến thức vào đây, hoặc tự viết ghi chú.",
  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Ghi chú xuất hiện khi AI lưu và làm sáng bộ não. Trang này thành bảng điều khiển của bạn khi ghi chú đầu tiên đến.",
  "Notes are not a password manager.": "Ghi chú không phải trình quản lý mật khẩu.",
  "Notes changed in the app or in the folder": "Ghi chú thay đổi trong ứng dụng hoặc trong thư mục",
  "Notes folder": "Thư mục ghi chú",
  "Notes folder switched": "Đã chuyển thư mục ghi chú",
  "Notes from {name}": "Ghi chú từ {name}",
  "Notes in the Obsidian Kanban format open as boards. Drag cards and lanes with a mouse or a finger, and every change lands in the note’s history.": "Ghi chú theo định dạng Obsidian Kanban sẽ mở dưới dạng bảng. Kéo thẻ và cột bằng chuột hoặc ngón tay, mọi thay đổi đều được ghi vào lịch sử của ghi chú.",
  "Notes in the current folder are not moved, copied or deleted. You can switch back here at any time.": "Ghi chú trong thư mục hiện tại không bị di chuyển, sao chép hay xóa. Bạn chuyển lại ở đây bất cứ lúc nào.",
  "Notes inside a folder": "Ghi chú trong thư mục",
