  "Nothing here": "Không có gì ở đây",
  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "Chưa ẩn gì: đánh dấu các tác nhân cần ẩn. Hiện cả {n} tác nhân đều thấy được.",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "Chưa ẩn gì: đánh dấu các tác nhân cần ẩn. Hiện tác nhân duy nhất đang thấy được.",
  "Nothing in 24h": "Không có trong 24 giờ",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "Không có gì trong tên ghi chú, thư mục hay văn bản, và không có gì viết gần giống. Thử ít chữ hơn, cách viết khác, hoặc một từ bên trong ghi chú.",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "Không có gì trong 24 giờ qua. Việc AI của bạn làm sẽ hiện ở đây khi xảy ra.",
  "Nothing in the log goes by “{name}”. Showing all activity.": "Không có gì trong nhật ký tên “{name}”. Đang hiện mọi hoạt động.",
