  "Nothing is allowed. Turn something on, or pause the agent instead.": "Không có gì được phép. Hãy bật gì đó, hoặc tạm dừng tác nhân.",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "Không mất gì: văn bản hiện tại vẫn nằm trong lịch sử là v{n}, nên bạn chuyển lại được bất cứ lúc nào.",
  "Nothing links here yet.": "Chưa có gì liên kết tới đây.",
  "Nothing matches": "Không có gì khớp",
