  "Nothing to compact yet": "Chưa có gì để thu gọn",
  "Nothing to delete": "Không có gì để xóa",
  "Nothing to save": "Không có gì để lưu",
  "Nothing to undo": "Không có gì để hoàn tác",
  "Nothing to undo: “{title}” is not pinned already.": "Không có gì để hoàn tác: “{title}” chưa được ghim.",
  "Nothing to undo: “{title}” is pinned already.": "Không có gì để hoàn tác: “{title}” đã được ghim.",
  "Nothing was heard": "Không nghe thấy gì",
  "Nothing yet": "Chưa có gì",
  "Nothing yet today": "Hôm nay chưa có gì",
  "Notifications": "Thông báo",
  "Notifications are blocked for this site. Allow them in the browser settings, then try again.": "Thông báo bị chặn cho trang này. Hãy cho phép trong cài đặt trình duyệt, rồi thử lại.",
  "Now": "Bây giờ",
  "Now ask {name} to save what it knows": "Giờ hãy nhờ {name} lưu những gì nó biết",
  "Nudge": "Huých",
  "OK": "OK",
  "Ocean": "Đại dương",
  "Off": "Tắt",
  "Off for every AI.": "Tắt cho mọi AI.",
  "Off for every agent": "Tắt cho mọi tác nhân",
  "Off: its models are hidden in chats": "Tắt: các mô hình của nó bị ẩn trong trò chuyện",
  "Off: tap to switch on": "Tắt: chạm để bật",
  "Offline": "Ngoại tuyến",
  "Offline · Memora": "Ngoại tuyến · Memora",
  "Offline, retrying": "Ngoại tuyến, đang thử lại",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Gemini CLI cũ không có <code>gemini mcp add</code>: thêm máy chủ vào <code>~/.gemini/settings.json</code> dưới <code>mcpServers</code>, với <code>httpUrl</code> và cùng tiêu đề.",
  "Older changes stay in History.": "Các thay đổi cũ hơn vẫn nằm trong Lịch sử.",
  "Older messages were left out to fit the model's context.": "Các tin nhắn cũ đã bị bỏ qua để vừa với ngữ cảnh của mô hình.",
  "Older than 30 days": "Cũ hơn 30 ngày",
  "Older than 7 days": "Cũ hơn 7 ngày",
  "Older than 90 days": "Cũ hơn 90 ngày",
  "Older versions of a note: read, compare, restore, and the trash.": "Các phiên bản cũ của ghi chú: đọc, so sánh, khôi phục, và thùng rác.",
  "Oldest entry": "Mục cũ nhất",
  "On": "Bật",
  "On a board": "Trên một bảng",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "Trên máy tính, kéo mép danh sách trò chuyện hoặc bảng bên để làm rộng hay hẹp lại. Mỗi bảng có độ rộng tối thiểu và nhớ độ rộng của mình.",
  "On hover": "Khi rê chuột",
  "On its avatar, its sparks in the brain and every activity row.": "Trên ảnh đại diện, tia lửa trong bộ não và mọi dòng hoạt động.",
  "On the Boards page each board has a ⋯ menu to open, rename, move, duplicate, colour or trash it. Right-click or a long press opens it too.": "Ở trang Bảng, mỗi bảng có menu ⋯ để mở, đổi tên, chuyển, nhân bản, đổi màu hoặc chuyển vào thùng rác. Nhấp chuột phải hoặc nhấn giữ cũng mở được menu.",
  "On this page": "Trên trang này",
  "On: tap to switch off": "Bật: chạm để tắt",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "Bật: {mnemo} ghi lại những gì nó nắm được trong trò chuyện. Tắt: chỉ những gì bạn thêm ở đây. Lưu ngay.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Sau khi cài, ứng dụng có biểu tượng riêng, mở toàn màn hình và vẫn truy cập được khi mất mạng.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Khi đã kết nối, hãy dán nội dung này vào một cuộc trò chuyện mới trong ứng dụng đó. Nó bảo AI lưu những gì nó biết vào Memora.",
  "Once its app is set up, every call shows up here as it happens.": "Khi ứng dụng của nó được thiết lập, mọi lượt gọi hiện ở đây khi xảy ra.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Khi {name} được kết nối, mọi thứ nó đọc, ghi và tìm hiện ở đây, trực tiếp.",
  "One address": "Một địa chỉ",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Một tác nhân cho mỗi ứng dụng hoặc thiết bị: khóa riêng, tên riêng trong Hoạt động, tắt riêng.",
  "One click": "Một lần nhấn",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Một thiết bị hoặc kết nối, như 203.0.113.7. Tìm \"what is my IP\" để biết địa chỉ của bạn.",
  "One device or connection.": "Một thiết bị hoặc kết nối.",
  "One folder of notes that you and every connected AI share.": "Một thư mục ghi chú mà bạn và mọi AI đã kết nối cùng dùng.",
  "One is hidden by the folder rule.": "Một cái bị quy tắc thư mục ẩn.",
  "One key per agent, its own permissions.": "Một khóa cho mỗi tác nhân, quyền riêng.",
  "One last step": "Bước cuối",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Một bộ nhớ mà mọi tác nhân đọc và ghi, và bạn xem, sửa và kết nối tất cả được.",
  "One memory for every AI": "Một bộ nhớ cho mọi AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Một ghi chú đang hiển thị ảnh này; ở đó nó sẽ hiện là bị thiếu. Lịch sử phiên bản vẫn giữ nó.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Mỗi dòng một mục. Chúng hiện trong phần gợi ý ở cuộc trò chuyện mới, đánh dấu Của bạn, và giữ cho đến khi bạn đổi.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Một bộ nhớ riêng tư chung cho bạn và các ứng dụng AI, để không phải giải thích hai lần.",
  "One set of notes for every AI app": "Một bộ ghi chú cho mọi ứng dụng AI",
  "One thin progress bar instead of stark lane bars, softer shadows, lane colours across the whole lane, and overdue shown as a stroke.": "Một thanh tiến độ mỏng thay cho các thanh cột nặng nề, bóng đổ mềm hơn, màu cột phủ toàn cột và quá hạn hiển thị bằng một nét gạch.",
  "Online": "Trực tuyến",
  "Only PNG, JPEG, WebP and GIF images can be added": "Chỉ thêm được ảnh PNG, JPEG, WebP và GIF",
  "Only in the current version": "Chỉ có ở phiên bản hiện tại",
  "Only in version {n}": "Chỉ có ở phiên bản {n}",
  "Only letters, digits and - _ / . can be used.": "Chỉ dùng được chữ, số và - _ / .",
  "Only looks at notes; changes nothing.": "Chỉ xem ghi chú; không thay đổi gì.",
  "Only looks things up and never writes. For agents with a read-only key.": "Chỉ tra cứu và không bao giờ ghi. Dành cho tác nhân có khóa chỉ đọc.",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "Chỉ hình ảnh trong tin nhắn mới nhất của bạn được gửi tới mô hình hình ảnh, và bạn được báo bằng một thông báo ngắn.",
  "Only reads and answers; never changes notes": "Chỉ đọc và trả lời; không bao giờ sửa ghi chú",
