  "Past due dates show in a warning tint and today’s in a softer one, and the Boards page counts what is overdue. A board’s own date colours win.": "Hạn đã qua hiện với màu cảnh báo, hạn hôm nay với màu nhạt hơn, và trang Bảng đếm số mục quá hạn. Màu ngày riêng của bảng được ưu tiên.",
