  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Dán vào terminal và nhấn <kbd>Enter</kbd>. Sau đó khởi động Claude Code, hoặc khởi động lại: Memora tự tải.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Dán vào terminal và nhấn <kbd>Enter</kbd>. Sau đó khởi động Gemini CLI, hoặc khởi động lại, rồi gõ <code>/mcp</code> để thấy Memora.",
  "Paste it into the app where it asks for a key.": "Dán vào ứng dụng ở chỗ yêu cầu khóa.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Dán vào tệp và lưu, rồi nhấn <b>Làm mới</b>. Memora sẽ hiện trong danh sách.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Dán vào tệp, lưu, rồi khởi động lại Claude Desktop. Máy này cần có Node.js.",
