  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Hãy lưu vào Memora những gì tôi đã chia sẻ với bạn về đời sống cá nhân: sở thích, thói quen, mục tiêu, những người quan trọng với tôi và điều tôi quan tâm. Đặt các ghi chú này trong thư mục tên Private, mỗi chủ đề một ghi chú, và liên kết các ghi chú liên quan. Không bao giờ lưu mật khẩu, số thẻ hay bí mật khác. Xong thì báo tôi đã lưu gì.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Hãy lưu vào Memora những gì bạn biết về công việc của tôi: vai trò, nhóm, các dự án tôi tham gia và tiến độ, cùng các quyết định đã đưa ra. Mỗi dự án hoặc chủ đề một ghi chú và liên kết chúng với nhau.",
