  "Start with the sidebar panel collapsed.": "Bắt đầu với bảng thanh bên thu gọn.",
  "Start writing": "Bắt đầu viết",
  "Starting the brain…": "Đang khởi động bộ não…",
  "Starts each session from the last journal entry and ends it with a dated session note and open todos.": "Bắt đầu mỗi phiên từ mục nhật ký cuối và kết thúc bằng ghi chú phiên có ngày và các việc còn mở.",
  "Starts with": "Bắt đầu bằng",
  "State folder writable": "Thư mục trạng thái ghi được",
  "Status": "Trạng thái",
  "Stay and edit": "Ở lại và sửa",
  "Step {n}": "Bước {n}",
