  "Step {n} of {total}: {name}": "Bước {n}/{total}: {name}",
  "Step {n} of {total}: {name}, done": "Bước {n}/{total}: {name}, xong",
  "Steps": "Các bước",
  "Steps are added, edited and checked as Mnemo works. Stop a reply and the plan stays as it was; it closes once every step is done.": "Các bước được thêm, sửa và đánh dấu khi Mnemo làm việc. Dừng câu trả lời thì kế hoạch vẫn như cũ; nó đóng lại khi mọi bước hoàn tất.",
  "Still running": "Vẫn đang chạy",
  "Still stopped. Start it on the server first.": "Vẫn dừng. Hãy khởi động nó trên máy chủ trước.",
  "Stop": "Dừng",
  "Stop Memora on the machine it runs on": "Dừng Memora trên máy đang chạy nó",
  "Stop Memora on the machine it runs on.": "Dừng Memora trên máy đang chạy nó.",
  "Stop and turn into text": "Dừng và chuyển thành văn bản",
