  "Stop filtering by #{tag}": "Ngừng lọc theo #{tag}",
  "Stop filtering by this pattern": "Ngừng lọc theo mẫu này",
  "Stop reading": "Dừng đọc",
  "Stop selecting": "Ngừng chọn",
