  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "Giờ bạn có trí nhớ dài hạn qua Memora. Hãy lưu vào Memora mọi thứ bạn biết về tôi từ các cuộc trò chuyện của chúng ta: tôi là ai, công việc, các dự án tôi tham gia, sở thích và các quyết định quan trọng. Mỗi chủ đề một ghi chú trong thư mục phù hợp, và liên kết các ghi chú liên quan. Xong thì báo tôi đã lưu gì.",
