  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} chỉ làm việc trong ghi chú của bạn. Mỗi thay đổi hiện trong Hoạt động và hoàn tác được từ Lịch sử.",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} đọc kho của bạn trong cuộc trò chuyện mới và giữ những gì học được ở đây.",
  "{mnemo} settings saved": "Đã lưu cài đặt {mnemo}",
  "{mnemo} settings: models and keys": "Cài đặt {mnemo}: mô hình và khóa",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "{mnemo} tự khởi chạy tác nhân phụ khi một tác vụ chia được; không cần thiết lập gì. Chúng chạy trên mô hình mặc định của bạn, rồi các mô hình dự phòng, trừ khi bạn nêu mô hình trong cuộc trò chuyện. Theo dõi chúng và đổi mô hình của chúng trong Tác nhân ở góc trên bên phải cuộc trò chuyện. Chúng dùng token riêng, nên ở Hỏi trước {mnemo} sẽ hỏi và nói khoảng bao nhiêu; ở Tự động thì chạy luôn. Lưu ngay.",
