  "{mnemo}'s own ({n})": "Của riêng {mnemo} ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "Ghi chú riêng của {mnemo} về cách nói chuyện với bạn, được đọc trong mọi cuộc trò chuyện. Nhấn một mục để đổi.",
