  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} không xem được ảnh; nó chỉ nhận tên ảnh. Hãy đặt một mô hình đọc được ảnh trong Cài đặt để ảnh được xem.",
