  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} không đọc được ảnh nên chỉ nhận tên ảnh. Hãy đặt một mô hình đọc được ảnh, hoặc đổi mô hình của cuộc trò chuyện này.",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} không đọc được ảnh nên nó chỉ nhận được tên ảnh. Hãy đặt một mô hình đọc được ảnh, hoặc đổi mô hình của cuộc trò chuyện này.",
